// ---------------------------------------------------------------------------
// Fill these in for your shop before running. See examples/README.md for the
// two-line SQL (or the admin paths) that gives you each id.
// ---------------------------------------------------------------------------
const TAX_ID = '00000000000000000000000000000000';           // Settings > Tax
const SALES_CHANNEL_ID = '00000000000000000000000000000000'; // Sales Channels
const CURRENCY_ID = 'b7d2554b0ce847cd82f3ac9bd1c0dfca';      // Shopware's default EUR (Defaults::CURRENCY)

if (TAX_ID.startsWith('0000') || SALES_CHANNEL_ID.startsWith('0000')) {
  throw new Error('Set TAX_ID and SALES_CHANNEL_ID at the top of this node - see examples/README.md');
}

// The Sync API upserts on the id you supply, so a stable id makes a workflow
// re-runnable: the first run creates, every later run updates the same record.
// n8n's Code sandbox disallows built-in modules, hence the inline hash.
const uuid = (seed) => {
  let h1 = 1779033703, h2 = 3144134277, h3 = 1013904242, h4 = 2773480762;
  for (let i = 0; i < seed.length; i++) {
    const k = seed.charCodeAt(i);
    h1 = h2 ^ Math.imul(h1 ^ k, 597399067);
    h2 = h3 ^ Math.imul(h2 ^ k, 2869860233);
    h3 = h4 ^ Math.imul(h3 ^ k, 951274213);
    h4 = h1 ^ Math.imul(h4 ^ k, 2716044179);
  }
  const part = (n) => (n >>> 0).toString(16).padStart(8, '0');
  return part(h1) + part(h2) + part(h3) + part(h4);
};

// Stand-in for a PIM/ERP feed - swap this array for an HTTP Request, a database
// node, or the Pimcore Datahub node. The mapping below is the part that matters:
// upstream ids become stable Shopware ids, so the sync is idempotent.
const source = [
  { sku: 'ERP-1001', title: 'Imported chair', priceGross: 89.0, quantity: 12 },
  { sku: 'ERP-1002', title: 'Imported table', priceGross: 249.0, quantity: 3 },
  { sku: 'ERP-1003', title: 'Imported shelf', priceGross: 129.5, quantity: 7 },
];

return source.map((row) => ({
  json: {
    id: uuid('erp:' + row.sku),
    productNumber: row.sku,
    name: row.title,
    stock: row.quantity,
    taxId: TAX_ID,
    active: true,
    price: [{
      currencyId: CURRENCY_ID,
      gross: row.priceGross,
      net: Math.round((row.priceGross / 1.19) * 100) / 100,
      linked: true,
    }],
    visibilities: [{
      id: uuid('visibility:erp:' + row.sku),
      salesChannelId: SALES_CHANNEL_ID,
      visibility: 30,
    }],
  },
}));
